21	public final class CompletableToSingle<T> extends Single<T> {
22	    final CompletableSource source;
23	
24	    final Supplier<? extends T> completionValueSupplier;
25	
26	    final T completionValue;
27	
28	    public CompletableToSingle(CompletableSource source,
29	            Supplier<? extends T> completionValueSupplier, T completionValue) {
30	        this.source = source;
31	        this.completionValue = completionValue;
32	        this.completionValueSupplier = completionValueSupplier;
33	    }
34	
35	    @Override
36	    protected void subscribeActual(final SingleObserver<? super T> observer) {
37	        source.subscribe(new ToSingle(observer));
38	    }
39	
40	    final class ToSingle implements CompletableObserver {
41	
42	        private final SingleObserver<? super T> observer;
43	
44	        ToSingle(SingleObserver<? super T> observer) {
45	            this.observer = observer;
46	        }
47	
48	        @Override
49	        public void onComplete() {
